"use client"

import type { ComponentProps as PlaygroundComponentProps } from "react"
import { useState } from "react";

import { Combobox, ComboboxContent, ComboboxEmpty, ComboboxInput, ComboboxItem, ComboboxList } from "@/components/ui/combobox";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Combobox>> = /*__DS_PROPS__*/ {}


const frameworks = ["Next.js", "React", "Vue", "Svelte", "Astro"]

export function ComboboxDemo() {
  const [value, setValue] = useState<string | null>(null)

  return (
    <Combobox items={frameworks} value={value} onValueChange={setValue}>{playgroundProps.children ?? <>
      <ComboboxInput
        placeholder="Select framework..."
        className="w-full max-w-xs"
      />
      <ComboboxContent>
        <ComboboxEmpty>No framework found.</ComboboxEmpty>
        <ComboboxList>
          {(item) => (
            <ComboboxItem key={item} value={item}>
              {item}
            </ComboboxItem>
          )}
        </ComboboxList>
      </ComboboxContent>
    </>}</Combobox>
  )
}

